#define PI 3.14159265358979
#define CS(a) = vec2(cos(a),sin(a))

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 R = iResolution.xy;
    vec2 uv = (2.*fragCoord-R)/R.x;
    vec2 olduv = uv;

    // Time varying pixel color    
    float scale = 12.;
    int N = 7;
    int offset = int(floor(float(N)/2.33));
    float t = iTime * 15.;
    int looptime = int(floor(mod(t,float(4*N-2))));
    float smoothlooptime = mod(t,float(4*N-2));


    vec3 angles = vec3(0.,2.*PI/3.,4.*PI/3.);

    uv.y += smoothlooptime / float(4*N-2) / (scale*sqrt(3.)/2.);

    vec3 xyz = floor((uv.x*cos(angles)+uv.y*sin(angles))*scale)/scale;
    //vec3 oldxyz = floor((olduv.x*cos(angles)+olduv.y*sin(angles))*scale)/scale;
    //vec3 xyz = uv.x*cos(angles)+uv.y*sin(angles);
    xyz.y -= smoothlooptime / float(4*N-2) / (scale);
    xyz.z += smoothlooptime / float(4*N-2) / (scale);

    ivec3 xyzi = ivec3(floor((uv.x*cos(angles)+uv.y*sin(angles))*scale));
    int xi = xyzi.x - offset * 2; // r
    int yi = xyzi.y + offset; // g
    int zi = xyzi.z + offset; // b


    // Output to screen
    //fragColor = vec4(sqrt(x)/2.,sqrt(y)/2.,sqrt(z)/2.,1.0);
    fragColor = vec4(pow(xyz, vec3(0.55)), 1.);
    //fragColor = vec4(oldxyz/2., 1);
    //fragColor = texture(iChannel0, fragCoord/R);

    // The staircase
    bool SE_TOP = zi >= -1 && zi <= N-2 && yi == -1;
    bool SE_BOT = zi >= 0 && zi <= N-1 && yi == -2;
    int SEtime = min(N+1, 1 + looptime);
    bool SE2TOP = SE_TOP && zi <= SEtime - 2;
    bool SE2BOT = SE_BOT && zi >= SEtime;
    bool SE = SE2TOP || SE2BOT;

    bool SW_TOP = zi == N-2 && yi <= N-1 && yi >= 0;;
    bool SW_BOT = zi == N-1 && yi <= N-2 && yi >= -1;
    int SWtime = min(N,max(0,looptime-(N-1)));
    bool SW_COVERED = zi==N-1 && xi == 1-N-SWtime && yi == -1+SWtime && SEtime >= N;
    bool SW2TOP = SW_TOP && yi <= SWtime-1;
    bool SW2BOT = SW_BOT && yi >= SWtime-1;
    bool SW = (SW2TOP || SW2BOT) && !SW_COVERED;

    bool NW_BOT = zi >= -1 && zi <= N-2 && -2+N == yi;
    bool NW_TOP = zi >= -2 && zi <= N-3 && -1+N == yi;
    int NWtime = min(N,max(0, looptime-(2*N-1)));
    bool NW_COVERED = NWtime > 0 && zi == N-2-NWtime && yi == -2+N && xi == -2*N+2+NWtime;
    bool NW2TOP = NW_TOP && zi >= N-2-NWtime;
    bool NW2BOT = NW_BOT && zi <= N-2-NWtime;
    bool NW = (NW2TOP || NW2BOT) && !NW_COVERED;

    bool NE = zi == -1 && yi <= N-3 && yi >= -1;
    bool NE_BOT = zi == -1 && yi <= N-3 && yi >= -1;
    bool NE_TOP = zi == -2 && yi <= N-2 && yi >= 0;
    int NEtime = max(0, looptime-(3*N-1));
    bool NE2BOT = NE_BOT && yi <= N-3-NEtime;
    bool NE2TOP = NE_TOP && yi >= N-1-NEtime;
    NE = NE2BOT || NE2TOP;

    if (SEtime == N+1) {
        SW = SW && !(zi==N-1 && xi == 2 && yi == -1);
    }
    if (SWtime == N) {
        NW = NW && zi <= N-2;
    }

    if(NW || NE || SW || SE) {
        fragColor=vec4(vec3(.8),1.);
    } else {


        // Inner left
        bool IN_L = xi <= -N+1 && xi >= -2*N+1 && yi <= N-2 && zi <=N-2;
        // Outer right
        bool OUT_R = xi >= -N+2 && xi <= 1 && yi <= -2;

        // Inner right
        bool IN_R = xi >= -N+2 && yi >= -1 && zi >=-1;
        // Outer left
        bool OUT_L = xi <= -N+1 && xi >= -2*N+1 && zi >= N-1 && !(SWtime < N && yi ==-1+N);

        // NE single block side
        bool NE_R = yi == N-2-NEtime && xi == -N + 2 + NEtime && looptime >= 3*N-1;
        // SE single block side.
        bool SE_L = zi == SEtime-1 && xi == 1 - SEtime && looptime < N;


        if(IN_L || OUT_R) {
            fragColor=vec4(vec3(.4),1.);
        }
        if(IN_R || OUT_L) {
            fragColor=vec4(vec3(.6),1.);
        }
        float inside_col_scale = olduv.y/1.3;
        if (IN_R || IN_L) {
            fragColor = vec4(fragColor.xyz + vec3(inside_col_scale), 1);
        }
        if(NE_R) {
            fragColor=vec4(vec3(.4),1.);
            if (NEtime < N) {
                fragColor = vec4(fragColor.xyz + vec3(max(0.,inside_col_scale)), 1);
            }
        }
        if(SE_L) {
            fragColor=vec4(vec3(.6),1.);
            if (SEtime == 1) {
                fragColor = vec4(fragColor.xyz + vec3(inside_col_scale), 1);
            }
        }
    }

}
